// 1. Get the message data from the immediately preceding Slack node
const message = $input.first().json;
const text = message.text || '';

// 2. Get the original trigger data (who reacted and with which emoji)
const triggerData = $('When Slack Reaction Added').first().json;
const reaction = triggerData.reaction || null;
const reactorId = triggerData.user || null; // The actual person who clicked the emoji

// 3. Extract fields from the newly formatted Slack message text
const employeeId = text.match(/\*Employee ID:\*\s*([^\n]+)/)?.[1]?.trim() || null;
const employeeName = text.match(/\*Employee:\*\s*([^\n]+)/)?.[1]?.trim() || null;
const managerName = text.match(/\*Manager:\*\s*([^\n]+)/)?.[1]?.trim() || null;

return [
  {
    json: {
      employeeId,
      employeeName,
      managerName,
      reaction,
      reactorId,
      messageTs: message.ts || null,
      channel: triggerData.item?.channel || null,
    }
  }
];

const inputItems = $input.all();
if (inputItems.length === 0) {
  return []; // reaction was on an unrelated message — ignore silently
}

const row = inputItems[0].json;
const reactionData = $('Parse Slack Event Data').first().json;

const activeStatuses = ['active', 'probation', 'on probation'];
const rowStatus = (row.Status || '').trim().toLowerCase();

if (!activeStatuses.includes(rowStatus)) {
  return [{
    json: {
      ...row,
      valid: false,
      rejectReason: `Decision already recorded for ${row.EmployeeName} (current status: ${row.Status}). This reaction was ignored.`,
      reactorId: reactionData.reactorId,
      channel: reactionData.channel,
      messageTs: reactionData.messageTs,
    },
  }];
}

const emojiMap = {
  white_check_mark: 'Confirmed',
  heavy_check_mark: 'Confirmed',
  arrows_counterclockwise: 'Extended',
  repeat: 'Extended',
  x: 'Terminated',
  no_entry: 'Terminated',
};

const decision = emojiMap[reactionData.reaction];
const isAuthorized = reactionData.reactorId === row.ManagerSlackID;

if (!decision || !isAuthorized) {
  return [{
    json: {
      ...row,
      valid: false,
      rejectReason: !decision
        ? `Unrecognized emoji for a probation decision: :${reactionData.reaction}:`
        : `Reaction came from an unauthorized user (expected the assigned manager).`,
      reactorId: reactionData.reactorId,
      channel: reactionData.channel,
      messageTs: reactionData.messageTs,
    },
  }];
}

const today = new Date().toISOString().split('T')[0];
let extendedUntil = '';
let remindersSent = row.RemindersSent || '';
let newStatus = decision; // 'Confirmed' or 'Terminated'

if (decision === 'Extended') {
  const newEnd = new Date();
  newEnd.setDate(newEnd.getDate() + 30);
  extendedUntil = newEnd.toISOString().split('T')[0];
  remindersSent = ''; // Reset reminders so the 30/15/0 day alerts trigger again!
  newStatus = row.Status; // Keep current probation status
}

return [{
  json: {
    ...row,
    valid: true,
    Status: newStatus,             // Updates the status so the loop stops (if confirmed/terminated)
    DecisionDate: today,           // Matches your sheet column
    DecidedBy: reactionData.reactorId, // Matches your sheet column
    ExtendedUntil: extendedUntil,  // Matches your sheet column
    RemindersSent: remindersSent,
    DecisionChannel: reactionData.channel,   // Matches your sheet column
    DecisionMessageTs: reactionData.messageTs // Matches your sheet column
  },
}];

const today = new Date();
today.setHours(0, 0, 0, 0);

const MS_PER_DAY = 1000 * 60 * 60 * 24;
const results = [];

for (const item of $input.all()) {
  const d = item.json;

  const status = String(d.Status || '')
    .trim()
    .toLowerCase();

  if (!['active', 'probation', 'on probation'].includes(status)) {
    continue;
  }

  // Handle RemindersSent safely
  let sentTiers = [];

  if (typeof d.RemindersSent === 'string') {
    sentTiers = d.RemindersSent
      .split(',')
      .map(s => s.trim())
      .filter(Boolean);
  }

  let deadline;

  // Extended probation
  if (d.ExtendedUntil && String(d.ExtendedUntil).trim()) {
    deadline = new Date(
      `${String(d.ExtendedUntil).trim()}T00:00:00`
    );
  } else {
    // Normal probation
    const startDate = new Date(
      `${String(d.StartDate).trim()}T00:00:00`
    );

    if (isNaN(startDate.getTime())) {
      continue;
    }

    const duration = Number(d.Duration);

    if (!Number.isFinite(duration) || duration <= 0) {
      continue;
    }

    deadline = new Date(startDate);
    deadline.setDate(deadline.getDate() + duration);
  }

  if (isNaN(deadline.getTime())) {
    continue;
  }

  const daysToDeadline = Math.floor(
    (deadline - today) / MS_PER_DAY
  );

  let tier = null;
  let message = '';

  // =========================
  // DECISION DUE
  // =========================
  if (daysToDeadline <= 0 && !sentTiers.includes('90')) {
    tier = '90';

    message =
      `*URGENT - Probation Decision Due*\n\n` +
      `*Employee ID:* ${d.EmployeeID}\n` +
      `*Employee:* ${d.EmployeeName}\n` +
      `*Manager:* ${d.ManagerName}\n\n` +
      `${d.EmployeeName}'s probation period ends today.\n\n` +
      `React on THIS message to record the outcome:\n` +
      `:white_check_mark: = Confirm\n` +
      `:arrows_counterclockwise: = Extend 30 days\n` +
      `:x: = Terminate`;
  }

  // =========================
  // 15 DAYS REMAINING
  // =========================
  else if (daysToDeadline <= 15 && !sentTiers.includes('75')) {
    tier = '75';

    message =
      `*Action Needed - Start Probation Review*\n\n` +
      `*Employee ID:* ${d.EmployeeID}\n` +
      `*Employee:* ${d.EmployeeName}\n` +
      `*Manager:* ${d.ManagerName}\n\n` +
      `${d.EmployeeName} reaches their probation decision deadline ` +
      `in *${daysToDeadline} days*.\n\n` +
      `Please begin filling out the review form now.`;
  }

  // =========================
  // 30 DAYS REMAINING
  // =========================
  else if (daysToDeadline <= 30 && !sentTiers.includes('60')) {
    tier = '60';

    message =
      `*Probation Reminder*\n\n` +
      `*Employee ID:* ${d.EmployeeID}\n` +
      `*Employee:* ${d.EmployeeName}\n` +
      `*Manager:* ${d.ManagerName}\n\n` +
      `${d.EmployeeName}'s probation period is entering its final month.\n\n` +
      `*${daysToDeadline} days* remain until the decision deadline.`;
  }

  // =========================
  // OUTPUT
  // =========================
  if (tier) {
    results.push({
      json: {
        ...d,
        tier,
        daysToDeadline,
        probationDeadline: deadline
          .toISOString()
          .split('T')[0],
        message,
        updatedRemindersSent: [
          ...sentTiers,
          tier
        ].join(', ')
      }
    });
  }
}

return results;

const d = $input.first().json;

const employeeId = (d['Employee ID'] || '').trim();
const employeeName = (d['Employee Name'] || '').trim();
const probationDuration = (d['Probation Duration (days)'] || '').trim();
const startDateRaw = d['Probation Start Date'];

const errors = [];

if (!employeeId) {
  errors.push('Employee ID is missing.');
}

if (!employeeName) {
  errors.push('Employee name is missing.');
}

if (!probationDuration) {
  errors.push('Probation duration is missing.');
} else if (isNaN(Number(probationDuration)) || Number(probationDuration) <= 0) {
  errors.push('Probation duration must be a valid number greater than 0.');
}

if (!startDateRaw) {
  errors.push('Probation start date is missing.');
}

return [{
  json: {
    EmployeeID: employeeId,
    EmployeeName: employeeName,
    ProbationDuration: Number(probationDuration),
    StartDate: startDateRaw,
    submissionValid: errors.length === 0,
    submissionErrors: errors.join(' ')
  }
}];

const submission = $('Prepare Form Submission Data').first().json;
const existingRows = $input.all().map((i) => i.json);

if (!submission.submissionValid) {
  return [{
    json: {
      ...submission,
      accepted: false,
      rejectReason: `Form validation failed: ${submission.submissionErrors}`,
    },
  }];
}

const idKey = submission.EmployeeID.trim().toLowerCase();
const isDuplicate = existingRows.some((row) => (row.EmployeeID || '').trim().toLowerCase() === idKey);

if (isDuplicate) {
  return [{
    json: {
      ...submission,
      accepted: false,
      rejectReason: `Employee ID ${submission.EmployeeID} is already in the probation tracker. Skipping duplicate entry.`,
    },
  }];
}

return [{
  json: {
    ...submission,
    accepted: true,
  },
}];
